import pytest
from subscription_api import validate_request

@pytest.mark.parametrize(('payload', 'expected_status', 'expected_error'), [
    ({'billing_email': 'billing@northstar.test', 'seats': 12}, 400, 'plan_code is required'),
    ({'plan_code': 'weekly', 'billing_email': 'billing@northstar.test', 'seats': 12}, 400, 'plan_code must be monthly or annual'),
    ({'plan_code': 'annual', 'billing_email': 'billing@northstar', 'seats': 12}, 400, 'billing_email must be a valid email address'),
    ({'plan_code': 'monthly', 'billing_email': 'billing@northstar.test', 'seats': True}, 400, 'seats must be an integer'),
    ({'plan_code': 'annual', 'billing_email': 'billing@northstar.test', 'seats': 250}, 201, ''),
])
def test_subscription_request_boundaries(payload, expected_status, expected_error):
    status_code, body = validate_request(payload)
    assert status_code == expected_status
    assert body.get('error', '') == expected_error
    if expected_status == 201:
        assert body == {'status': 'accepted'}

