import re

def validate_request(payload):
    if 'plan_code' not in payload:
        return 400, {'error': 'plan_code is required'}
    plan_code = payload['plan_code']
    if not isinstance(plan_code, str) or plan_code not in {'monthly', 'annual'}:
        return 400, {'error': 'plan_code must be monthly or annual'}
    if 'billing_email' not in payload:
        return 400, {'error': 'billing_email is required'}
    email = payload['billing_email']
    if not isinstance(email, str) or re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email) is None:
        return 400, {'error': 'billing_email must be a valid email address'}
    if 'seats' not in payload:
        return 400, {'error': 'seats is required'}
    seats = payload['seats']
    if isinstance(seats, bool) or not isinstance(seats, int):
        return 400, {'error': 'seats must be an integer'}
    if not 1 <= seats <= 250:
        return 400, {'error': 'seats must be between 1 and 250'}
    return 201, {'status': 'accepted'}

