import re
from datetime import date

def validate_request(payload):
    if 'sku' not in payload:
        return 400, {'error': 'sku is required'}
    sku = payload['sku']
    if not isinstance(sku, str) or re.fullmatch(r'[A-Z]{3}-[0-9]{6}', sku) is None:
        return 400, {'error': 'sku must match the required format'}
    if 'quantity' not in payload:
        return 400, {'error': 'quantity is required'}
    quantity = payload['quantity']
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        return 400, {'error': 'quantity must be an integer'}
    if not 1 <= quantity <= 500:
        return 400, {'error': 'quantity must be between 1 and 500'}
    if 'delivery_date' not in payload:
        return 400, {'error': 'delivery_date is required'}
    delivery_date = payload['delivery_date']
    if not isinstance(delivery_date, str) or re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}', delivery_date) is None:
        return 400, {'error': 'delivery_date must use YYYY-MM-DD'}
    try:
        date.fromisoformat(delivery_date)
    except ValueError:
        return 400, {'error': 'delivery_date must be a valid calendar date'}
    return 201, {'status': 'accepted'}
